        .option("bar", { type: "string", alias: "b", required: true })
        .option("baz", { type: "string", required: false, hidden: true })
        .middleware((argv) => {
          const { foo, bar } = argv;
          argv.baz = `${foo} ${bar}`;
        }),
    (argv) => {
      const { baz } = argv;
             //^? string | undefined
      console.log({ baz });
    }
  )
  .strict()
  .parse();

```

There are two issues with this:

1) The `baz` type is `string | undefined` and not `string`.
2) One has to declare `baz` as an option and make it `hidden`. Which is not good as user can set it still:

```
