  }
);

cp.stdout.on('data', (chunk) => {
  process.stdout.write(chunk.toString());
});
```

Running the above script will only print a small portion of the entire help - the help output is going to be cut.

I feel, maybe, it should be push from `yargs` to make people stop using `process.exit()` API as documentation in Node.js very clearly states that `process.exit()` is "ungraceful shutdown":

https://nodejs.org/api/process.html#processexitcode
> Calling process.exit() will force the process to exit as quickly as possible even if there are still asynchronous operations pending that have not yet completed fully, including I/O operations to process.stdout and process.stderr.

> Can you confirm that the truncation stops if you remove the check for `stream.isTTY`, if it does, I would happily take a PR for this fix.

To my surprise, the truncation did not stop after removing this check. Here's the `setBlocking` function I tested with: https://github.com/yargs/yargs/pull/2253

https://github.com/yargs/yargs/blob/12aca226012da81167a84812c008a1e95e6f12c7/lib/utils/set-blocking.ts#L8-L17

I tested this change on the following script:

```js
const yargs = require("yargs");

yargs
    .scriptName("print-lorem-ipsum")
    .command('test', 'Print lorem ipsum to reproduce truncation.', (yargs) => {
        yargs.option('blocking', {
            type: 'boolean',
            default: false,
            global: false,
            boolean: true,
            describe: 'Whether or not to set stdout and stderr to be blocking before the command runs.'
        })
    }, async function (args) {
        console.log(process.stdout._handle.blocking);

        // If setBlocking(true) is called within the script, no truncation happens regardless of piping.
        if (args.blocking) {
            process.stdout._handle.setBlocking(true);
            process.stderr._handle.setBlocking(true);
        }

        const text = [
            ...[...new Array(1000)]
                .map(x => "Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do eiusmod..."),
            "",
            "┌────────────────────────────────┐",
            "│                                │",
            "│   End of lorem ipsum output.   │",
            "│                                │",
            "└────────────────────────────────┘",
            ""
        ].join("\n");

        console.log(text)

        throw new Error("Throwing an error to reproduce truncation.");
    })
    .help()
    .argv
```

Running this script without a pipe shows expected results.

```sh
node index.js test
```

