For posterity / if anyone else encounters this, the workaround I'm using is to manually define an option named "version" that simulates the version lookup in package.json, but only if no other arguments were passed:

```js
#!/usr/bin/env node
const yargs = require('yargs/yargs')
const fs = require('fs-extra');

const ya = yargs(process.argv)
  .version(false)
  .option('version', {
    description: 'Show version number',
    type: 'boolean',
    global: false,
  })
  .command('serve [port]', 'start the server', (yargs) => {
    return yargs
      .positional('port', {
        describe: 'port to bind on',
        default: 5000
      })
  }, (argv) => {
    if (argv.verbose) console.info(`start server on :${argv.port}`)
    serve(argv.port)
  });

const args = ya.argv;

if (args._.length === 2 && args.version === true) {
  const pkgPath = require.resolve('./package.json');
  const pkg = fs.readJsonSync(pkgPath);
  console.log(pkg.version);
  process.exit(0);
}
```

