```typescript
interface IHandlerExitOptions {
  exitProcess?: boolean;
}

/**
 * Unfortunately yargs does not allow global handling of command handler results.
 * This may be fixed this https://github.com/nyamadori/yargs/pull/1 in the future.
 * For now we hook into `require.extensions` and hook the individual command handlers
 * to achieve this global handling.
 * This hook also modifies all commands to exit by default unless an object with `exitProcess: false`
 * is resolved.
 */
function hookYargsHandlers() {
  const oldHandler = require.extensions['.js'];

  const binPath = resolve(__dirname, 'bin');
  require.extensions['.js'] = function(m: NodeModule, fileName: string) {
    const ret = oldHandler.call(this, m, fileName);
    if (fileName.startsWith(binPath)) {
      const command: yargs.CommandModule = m.exports.command;
      const handler = <(args: any) => Promise<void | IHandlerExitOptions> | void>command.handler;
      command.handler = async function(args: any) {
        const res = await handler.call(this, args);
        if (!res || res.exitProcess === undefined || res.exitProcess) {
          process.exit(0);
        }
        // Technically redundant because ignored but might not be in the future.
        return res;
      };
      m.exports = command;
    }
    return ret;
  };
}

hookYargsHandlers();
```

