  // We need to declare this already here as we don't
  // have the context anymore after the await call
  const help = this.getUsageInstance().help()

  // Handle yargs errors
  if (err && err.name === 'YError') {
    console.error(`${help}\n\n${err.message}`)
    return process.exit(1)
  } else if (err) {
    console.error(`${help}\n\n${err.stack}`)
    return process.exit(1)
  }

  let _err
  if (argv.___promise) {
    try {
      await argv.___promise
    } catch (error) {
      _err = error
    }
  }

  if (process.env.DEBUG) console.debug('exit handler resolved', {err, argv, output}) // eslint-disable-line no-console, max-len

  // Log the help and the error if we have one.
  // We force the exit here while other runs should gracefully shutdown
  if (_err) {
    console.error(`${help}\n\n`, _err)
    return process.exit(1)
  }
