      describe: 'Some description',
      type: 'boolean'
    })
  }, ({raw}) => {
    console.log('is raw:', raw)
  })
  .argv
```

It looks like the fix applied in #962 only applies to the `.option()` method and not to the type-specific methods like `.boolean()`. We should probably leave this issue open to address this.

In the meantime, please use one of the above workarounds. Thanks!

