The first method ([this one](https://github.com/yargs/yargs/issues/793#issuecomment-521250679)) has major problems with commands, options, and the help message. If commands are included before both parses, they would end up in the help, but they'd also be executed twice and the first time wouldn't have the correct default value. Alternatively, if a validation is failed in the first parse, and commands are only added after the second parse, then they don't show up in the help. Similarly, duplicating options to exist for both the first and second parse is problematic because yargs doesn't reevaluate the option once it has been parsed the first time. Meaning the new default value isn't used. But if the option isn't before the first parse, then it doesn't show up in the help. 

```js
const yargs = require("yargs")

let processYargs = (args) => yargs
    .option( "ssl", {
        required: yargs.finishedParse, // otherwise it can fail early
    })
    .option( "port",  {
        
        // the useful part
        default: (()=>{
            if (!yargs.finishedParse) {
                return 99999
            } else if (!args._.includes("--port") {
                return args.port = 443
            }
        })(),
        
    })
    .command({
        handler: async (args) => {
            //
            // Caveat: need these 2 lines otherwise command will run twice or not wait on argument processing
            //
            if (!require("yargs").finishedParse) return
            await require("yargs").secondParseFinished

                 // actual code here //
        },
        command: "generate-specs [fixtures..]",
        desc: "(re)generate spec files",
        builder: (yargs) => {},
    })
)

const { hideBin } = require('yargs/helpers')
global.args = ()=>yargs.argv
;((async ()=>{
    await new Promise((resolve, reject)=>processYargs().parse(hideBin(process.argv), resolve))
    yargs.finishedParse = true
    yargs.secondParseFinished = new Promise((resolve, reject)=>processYargs(yargs.argv).parse(hideBin(process.argv), resolve))
})())
```

