comments.body:
I suppose this is covered by `.check` but keeping the grouping logic(items in group) more tight would be nice.

``` js
var opts = require('yargs')
  .option('id', {
     description: 'Unique user id from mongo'
   })
  .option('username', {
     description: '...'
   })
  .option('email', {
     description: 'Email associated with the user'
  })
  .check(function(argv) {
    return argv.id || argv.username || argv.email;
  })
```

Keeping the group logic more single source of truth:

``` js
var identifyUserGroup = ['id', 'username', 'email'];

var opts = require('yargs')
  .option('id', {
     description: 'Unique user id from mongo'
   })
  .option('username', {
     description: '...'
   })
  .option('email', {
     description: 'Email associated with the user'
  })
  .group(identifyUserGroup, 'Identify user by')
  .check(function(argv) {
    return identifyUserGroup.reduce(function(prev, optionKey) {
      return prev || argv[optionKey];
    }, false);
  })
```
